import collections

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    if not grid or not rows or not cols:
        return grid

    # Identify background color: most frequent color
    counts = collections.Counter()
    for row in grid:
        for val in row:
            counts[val] += 1
    background = counts.most_common(1)[0][0]
    target_fill = 8

    visited = [[False] * cols for _ in range(rows)]
    components = []

    # Find connected components of non-background colors
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != background and not visited[r][c]:
                cells = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == val:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                components.append((val, cells))

    # Process components
    result = [row[:] for row in grid]
    for color, cells in components:
        if not cells:
            continue

        r_min = min(r for r, c in cells)
        r_max = max(r for r, c in cells)
        c_min = min(c for r, c in cells)
        c_max = max(c for r, c in cells)

        # Fill interior of bounding box
        for r in range(r_min + 1, r_max):
            for c in range(c_min + 1, c_max):
                if grid[r][c] == color:
                    result[r][c] = target_fill

    return result
